 * Parsing of the build-graph text format described in the task prompt.
 */

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

class LineError extends Error {
  constructor(line, message) {
    super(message)
    this.type = 'line'
    this.line = line
  }
}

class UnknownTaskError extends Error {
  constructor(name) {
    super(`unknown task ${name}`)
    this.type = 'unknown'
    this.name_ = name
  }
}

/**
 * Parses the input text into a graph description.
 *
 * Returns { tasks, deps } where tasks maps name -> { cost, line } and deps
 * maps name -> Set of dependency names. Throws LineError or UnknownTaskError
 * on invalid input.
 */
function parseInput(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const tasks = new Map()
  const deps = new Map()
  const references = [] // names used by dep lines, in input order

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new LineError(lineNo, 'expected task <name> <cost>')
      }
      const name = words[1]
      const costStr = words[2]
      if (!NAME_RE.test(name)) {
        throw new LineError(lineNo, `invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new LineError(lineNo, 'cost must be a non-negative integer')
      }
      if (tasks.has(name)) {
        throw new LineError(lineNo, `task ${name} is declared twice`)
      }
      tasks.set(name, { cost: parseInt(costStr, 10), line: lineNo })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new LineError(lineNo, 'expected dep <name> <dependency>...')
      }
      const name = words[1]
      const depNames = words.slice(2)
      const allNames = [name, ...depNames]
      for (const n of allNames) {
        if (!NAME_RE.test(n)) {
          throw new LineError(lineNo, `invalid task name ${n}`)
        }
      }
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      references.push(name)
      for (const d of depNames) {
        set.add(d)
        references.push(d)
      }
    } else {
      throw new LineError(lineNo, `unknown directive ${directive}`)
    }
  }

  for (const n of references) {
    if (!tasks.has(n)) {
      throw new UnknownTaskError(n)
    }
  }

  return { tasks, deps }
}

export { parseInput, LineError, UnknownTaskError }
"}

