{"file_path":"src/graph.js","content":"/**
 * Graph algorithms shared by waves/explain/pack: cycle detection, topological
 * ordering, timing (start/finish/depth) and pack priority computation.
 */

function sortedNames(tasks) {
  return [...tasks.keys()].sort()
}

function sortedDeps(deps, name) {
  const s = deps.get(name)
  return s ? [...s].sort() : []
}

/**
 * Depth-first search from each task in ascending name order, walking each
 * task's dependencies in ascending name order, looking for the first cycle
 * re-entered. Returns an array of names describing the cycle (closed, first
 * name repeated at the end) or null when the graph is acyclic.
 */
function detectCycle(tasks, deps) {
  const names = sortedNames(tasks)
  const state = new Map()
  for (const n of names) state.set(n, 0) // 0 = unvisited, 1 = visiting, 2 = done

  for (const start of names) {
    if (state.get(start) !== 0) continue

    const stack = [{ node: start, children: sortedDeps(deps, start), idx: 0 }]
    const path = [start]
    state.set(start, 1)

    while (stack.length) {
      const frame = stack[stack.length - 1]
      if (frame.idx < frame.children.length) {
        const v = frame.children[frame.idx++]
        const st = state.get(v)
        if (st === 1) {
          const idx = path.indexOf(v)
          return path.slice(idx).concat([v])
        } else if (st === 0) {
          state.set(v, 1)
          path.push(v)
          stack.push({ node: v, children: sortedDeps(deps, v), idx: 0 })
        }
        // st === 2: already fully explored, no cycle through this edge
      } else {
        state.set(frame.node, 2)
        stack.pop()
        path.pop()
      }
    }
  }

  return null
}

/**
 * Builds the dependents map: name -> array of names that directly depend on
 * it (i.e. list it in a dep line).
 */
function buildDependents(tasks, deps) {
  const dependents = new Map()
  for (const n of tasks.keys()) dependents.set(n, [])
  for (const [name, set] of deps) {
    for (const d of set) {
      dependents.get(d).push(name)
    }
  }
  return dependents
}

/**
 * Topological order (dependencies before dependents), assuming the graph is
 * acyclic. Returns { order, dependents }.
 */
function topoOrder(tasks, deps) {
  const dependents = buildDependents(tasks, deps)
  const indeg = new Map()
  for (const n of tasks.keys()) indeg.set(n, deps.has(n) ? deps.get(n).size : 0)

  const queue = []
  for (const n of tasks.keys()) if (indeg.get(n) === 0) queue.push(n)

  const order = []
  let qi = 0
  while (qi < queue.length) {
    const u = queue[qi++]
    order.push(u)
    for (const v of dependents.get(u)) {
      indeg.set(v, indeg.get(v) - 1)
      if (indeg.get(v) === 0) queue.push(v)
    }
  }

  return { order, dependents }
}

/**
 * Computes start, finish and depth (wave) for every task, given a
 * dependency-respecting topological order.
 */
function computeTimes(tasks, deps, order) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  for (const name of order) {
    const ds = sortedDeps(deps, name)
    let s = 0
    let d = 0
    if (ds.length > 0) {
      s = Math.max(...ds.map((x) => finish.get(x)))
      d = Math.max(...ds.map((x) => depth.get(x))) + 1
    }
    const cost = tasks.get(name).cost
    start.set(name, s)
    finish.set(name, s + cost)
    depth.set(name, d)
  }

  return { start, finish, depth }
}

/**
 * Computes pack priority: the cost of the longest chain starting at a task
 * and following dependents down to a task nothing depends on.
 */
function computePriority(tasks, dependents, order) {
  const priority = new Map()
  const rev = [...order].reverse()

  for (const name of rev) {
    const cost = tasks.get(name).cost
    const children = dependents.get(name) || []
    if (children.length === 0) {
      priority.set(name, cost)
    } else {
      priority.set(name, cost + Math.max(...children.map((c) => priority.get(c))))
    }
  }

  return priority
}

export { detectCycle, topoOrder, computeTimes, computePriority, sortedNames }
"}

