 * Simulates packing the build graph onto a fixed number of workers.
 */

function simulatePack(tasks, deps, dependents, priority, workers) {
  const names = [...tasks.keys()]
  const total = names.length

  const depsRemaining = new Map()
  for (const n of names) depsRemaining.set(n, deps.has(n) ? deps.get(n).size : 0)

  const ready = new Set()
  for (const n of names) if (depsRemaining.get(n) === 0) ready.add(n)

  const workerFree = new Array(workers).fill(0)
  const workerLog = Array.from({ length: workers }, () => [])

  // Pending completions: tasks that have started but whose finish is still
  // in the future relative to currentTime.
  let pending = [] // { time, name }

  let currentTime = 0
  let scheduled = 0

  function processCompletion(name) {
    for (const dep of dependents.get(name) || []) {
      depsRemaining.set(dep, depsRemaining.get(dep) - 1)
      if (depsRemaining.get(dep) === 0) ready.add(dep)
    }
  }

  while (scheduled < total) {
    // Assign as much as possible at currentTime.
    let progressed = true
    while (progressed) {
      progressed = false
      // Find free workers at currentTime.
      let freeIdx = -1
      for (let i = 0; i < workers; i++) {
        if (workerFree[i] <= currentTime) {
          freeIdx = i
          break
        }
      }
      if (freeIdx === -1 || ready.size === 0) break

      // Choose the ready task with greatest priority, ties by ascending name.
      let best = null
      for (const cand of ready) {
        if (
          best === null ||
          priority.get(cand) > priority.get(best) ||
          (priority.get(cand) === priority.get(best) && cand < best)
        ) {
          best = cand
        }
      }

      const cost = tasks.get(best).cost
      const start = currentTime
      const finish = start + cost
      workerLog[freeIdx].push({ name: best, start, finish })
      workerFree[freeIdx] = finish
      ready.delete(best)
      scheduled++

      if (finish <= currentTime) {
        processCompletion(best)
      } else {
        pending.push({ time: finish, name: best })
      }

      progressed = true
    }

    if (scheduled >= total) break

    // Advance time to the next instant a worker becomes free.
    if (pending.length === 0) {
      // Should not happen for a valid acyclic graph, but guard against
      // infinite loop just in case.
      break
    }
    let nextTime = Infinity
    for (const p of pending) if (p.time < nextTime) nextTime = p.time
    currentTime = nextTime

    const stillPending = []
    for (const p of pending) {
      if (p.time === currentTime) {
        processCompletion(p.name)
      } else {
        stillPending.push(p)
      }
    }
    pending = stillPending
  }

  return workerLog
}

export { simulatePack }
"}

