{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import fs from 'node:fs'
import { parseInput } from './parse.js'
import { detectCycle, topoOrder, computeTimes, computePriority, sortedNames } from './graph.js'
import { simulatePack } from './pack.js'

const WORKERS_RE = /^[1-9][0-9]*$/

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function usageFail() {
  fail('usage: cli.js waves|explain|pack <workers>')
}

function main() {
  const args = process.argv.slice(2)

  let mode
  let workers = null

  if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) {
    mode = args[0]
  } else if (args.length === 2 && args[0] === 'pack') {
    mode = 'pack'
    if (!WORKERS_RE.test(args[1])) {
      fail('workers must be a positive integer')
    }
    workers = parseInt(args[1], 10)
  } else {
    usageFail()
  }

  let text
  try {
    text = fs.readFileSync(0, 'utf8')
  } catch {
    text = ''
  }

  let tasks
  let deps
  try {
    ;({ tasks, deps } = parseInput(text))
  } catch (err) {
    if (err.type === 'line') {
      fail(`line ${err.line}: ${err.message}`)
    } else if (err.type === 'unknown') {
      fail(err.message)
    }
    throw err
  }

  const cycle = detectCycle(tasks, deps)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
  }

  const { order, dependents } = topoOrder(tasks, deps)
  const { start, finish, depth } = computeTimes(tasks, deps, order)
  const names = sortedNames(tasks)

  let total = 0
  for (const n of names) if (finish.get(n) > total) total = finish.get(n)

  const lines = []

  if (mode === 'waves') {
    let maxDepth = -1
    for (const n of names) if (depth.get(n) > maxDepth) maxDepth = depth.get(n)
    for (let k = 0; k <= maxDepth; k++) {
      const inWave = names.filter((n) => depth.get(n) === k).sort()
      lines.push(`wave ${k}: ${inWave.join(' ')}`)
    }
    lines.push(`total ${total}`)
  } else if (mode === 'explain') {
    for (const n of names) {
      lines.push(`${n} start=${start.get(n)} finish=${finish.get(n)} depth=${depth.get(n)}`)
    }
    lines.push(`total ${total}`)
  } else if (mode === 'pack') {
    const priority = computePriority(tasks, dependents, order)
    const workerLog = simulatePack(tasks, deps, dependents, priority, workers)
    let makespan = 0
    for (const w of workerLog) for (const e of w) if (e.finish > makespan) makespan = e.finish
    for (let i = 0; i < workers; i++) {
      const parts = workerLog[i].map((e) => ` ${e.name}@${e.start}-${e.finish}`).join('')
      lines.push(`worker ${i}:${parts}`)
    }
    lines.push(`makespan ${makespan}`)
  }

  process.stdout.write(lines.join('\n') + '\n')
}

main()
"}

